/* From Uiverse.io by BHARGAVPATEL1244 - Tags: button */
.__UIV_SCOPE__ button {
 outline: none;
 cursor: pointer;
 border: none;
 padding: 0.9rem 2rem;
 margin: 0;
 font-family: inherit;
 font-size: inherit;
 position: relative;
 display: inline-block;
 letter-spacing: 0.05rem;
 font-weight: 700;
 font-size: 17px;
 border-radius: 500px;
 overflow: hidden;
 background: #66ff66;
 color: ghostwhite;
}

.__UIV_SCOPE__ button span {
 position: relative;
 z-index: 10;
 transition: color 0.4s;
}

.__UIV_SCOPE__ button:hover span {
 color: black;
}

.__UIV_SCOPE__ button::before,
.__UIV_SCOPE__ button::after {
 position: absolute;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 z-index: 0;
}

.__UIV_SCOPE__ button::before {
 content: "";
 background: #000;
 width: 120%;
 left: -10%;
 transform: skew(30deg);
 transition: transform 0.4s cubic-bezier(0.3, 1, 0.8, 1);
}

.__UIV_SCOPE__ button:hover::before {
 transform: translate3d(100%, 0, 0);
}
